async function main() {
  let created = 0;
  let updated = 0;
  for (const c of clients) {
    const existing = await prisma.client.findUnique({ where: { code: c.code } });
    await prisma.client.upsert({ where: { code: c.code }, create: c, update: c });
    if (existing) {
      updated++;
    } else {
      created++;
    }
  }
  console.log(`Clients seeded - ${created} created, ${updated} updated.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
